<template>
  <div class="my-learning">
    <div class="learning-toolbar"><h1>我的学习</h1><div><button type="button" @click="rulesOpen = true">统计规则</button><button type="button" :disabled="loading || saving" @click="load">刷新</button></div></div>
    <p v-if="error" class="learning-error" role="alert">{{ error }}</p>
    <div v-if="loading && !dashboard" class="learning-empty">加载中…</div>
    <template v-if="dashboard">
      <div class="learning-stats"><div><span>已完成实验</span><strong>{{ summary.finishedCount }}<small>/ {{ summary.assignedCount }}</small></strong></div><div><span>报告均分</span><strong>{{ summary.averageScore ?? '—' }}</strong></div><div><span>学习积分</span><strong class="brand-value">{{ summary.totalPoints }}</strong></div><div><span>班级排名</span><strong>{{ dashboard.selfRank || '—' }}</strong></div></div>
      <div class="learning-columns">
        <section class="learning-panel records-panel">
          <nav class="learning-tabs" aria-label="学习记录分类"><button v-for="tab in tabs" :key="tab.key" type="button" :class="{ active: selectedTab === tab.key }" :aria-pressed="selectedTab === tab.key" @click="selectedTab = tab.key">{{ tab.label }}<span v-if="tab.count != null">{{ tab.count }}</span></button></nav>
          <div v-if="!visibleRecords.length" class="learning-empty">{{ selectedTab === 'pending' ? '暂无待办' : selectedTab === 'feedback' ? '暂无教师反馈' : '暂无记录' }}</div>
          <div v-else-if="selectedTab === 'feedback'" class="feedback-list"><article v-for="record in visibleRecords" :key="record.code"><header><strong>{{ record.name }}</strong><span class="score-tag">{{ record.score == null ? '已批阅' : record.score + ' 分' }}</span></header><p class="teacher-comment">{{ record.comment || '暂无评语' }}</p><div v-if="record.reflection" class="reflection-content"><strong>我的订正</strong><p>{{ record.reflection }}</p><span class="record-status" :class="{ done: record.reflectionCurrent }">{{ record.reflectionCurrent ? '已订正' : '反馈已更新' }}</span></div><footer><span>{{ learningDate(record.gradedAt) }}</span><div><button type="button" @click="openRecord(record)">查看报告</button><button type="button" class="primary" @click="editReflection(record)">{{ record.reflectionCurrent ? '修改订正' : '填写订正' }}</button></div></footer></article></div>
          <div v-else-if="selectedTab === 'points'" class="point-list"><article v-for="record in visibleRecords" :key="record.code"><header><strong>{{ record.name }}</strong><b>+{{ record.points }}</b></header><div class="point-items"><span v-for="item in record.pointItems" :key="item.label">{{ item.label }}<b>+{{ item.points }}</b></span></div></article></div>
          <div v-else class="record-table-wrap"><table class="record-table"><thead><tr><th>实验</th><th>状态</th><th>{{ selectedTab === 'pending' ? '截止时间' : '完成时间' }}</th><th>积分</th><th></th></tr></thead><tbody><tr v-for="record in visibleRecords" :key="record.code"><td><strong>{{ record.name }}</strong><span class="record-class">{{ record.className }}</span></td><td><span class="record-status" :class="{ done: record.graded, pending: record.currentTask || record.state === 'REPORT_PENDING' }">{{ selectedTab === 'pending' && record.graded ? '待订正' : learningState(record.state) }}</span></td><td :class="{ overdue: overdue(record) }">{{ learningDate(selectedTab === 'pending' ? record.dueAt : record.finishedAt) }}</td><td>{{ record.points }}</td><td><button v-if="record.graded && selectedTab === 'pending'" type="button" class="text-action" @click="editReflection(record)">填写订正</button><button v-else type="button" class="text-action" :disabled="record.state === 'QUEUED'" @click="openRecord(record)">{{ record.finished ? '查看报告' : record.currentTask ? '继续学习' : '待开始' }}</button></td></tr></tbody></table></div>
        </section>
        <aside class="learning-sidebar"><section class="learning-panel"><header class="panel-heading"><h2>能力雷达</h2></header><LearningRadar :dimensions="summary.dimensions" /></section><section class="learning-panel ranking-panel"><header class="panel-heading"><h2>班级排行</h2><select v-model="className" :disabled="loading || saving" aria-label="选择排行班级" @change="load"><option v-for="name in dashboard.classes" :key="name" :value="name">{{ name }}</option></select></header><LearningRanking :rows="dashboard.leaderboard" /></section></aside>
      </div>
    </template>
    <LearningRulesDialog v-if="rulesOpen" @close="rulesOpen = false" />
    <div v-if="reflectionRecord" class="learning-mask" @click.self="closeReflection" @keydown.esc="closeReflection"><form class="learning-dialog" role="dialog" aria-modal="true" aria-label="反馈订正" @submit.prevent="saveReflection"><header><h2>反馈订正</h2><button type="button" :disabled="saving" @click="closeReflection">关闭</button></header><h3>{{ reflectionRecord.name }}</h3><label>教师评语</label><p class="dialog-comment">{{ reflectionRecord.comment || '暂无评语' }}</p><label for="learning-reflection">订正内容</label><textarea ref="reflectionInput" id="learning-reflection" v-model.trim="reflectionText" required maxlength="2000" rows="7" :disabled="saving" /><p v-if="reflectionError" class="learning-error" role="alert">{{ reflectionError }}</p><footer><span>{{ reflectionText.length }} / 2000</span><button type="submit" class="primary" :disabled="saving || !reflectionText">{{ saving ? '提交中…' : '提交订正' }}</button></footer></form></div>
  </div>
</template>
<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { learningApi, learningError } from '../api/learning'
import { feedbackLearning, learningDate, learningState, pendingLearning, recordRoute } from '../utils/learning'
import LearningRadar from '../components/learning/LearningRadar.vue'
import LearningRanking from '../components/learning/LearningRanking.vue'
import LearningRulesDialog from '../components/learning/LearningRulesDialog.vue'
const router = useRouter(), dashboard = ref(null), loading = ref(false), error = ref(''), className = ref(''), selectedTab = ref('pending'), rulesOpen = ref(false)
const reflectionRecord = ref(null), reflectionText = ref(''), reflectionError = ref(''), reflectionInput = ref(null), saving = ref(false)
const summary = computed(() => dashboard.value?.summary)
const records = computed(() => summary.value?.records || [])
const tabs = computed(() => [{ key: 'pending', label: '待办任务', count: pendingLearning(records.value).length }, { key: 'feedback', label: '反馈订正', count: feedbackLearning(records.value).length }, { key: 'records', label: '实验记录' }, { key: 'points', label: '积分明细' }])
const visibleRecords = computed(() => selectedTab.value === 'pending' ? pendingLearning(records.value) : selectedTab.value === 'feedback' ? feedbackLearning(records.value).slice().reverse() : selectedTab.value === 'points' ? records.value.filter(r => r.points > 0) : records.value)
let sequence = 0
async function load() {
  const run = ++sequence; loading.value = true; error.value = ''
  try { const { data } = await learningApi.student(className.value || undefined); if (run !== sequence) return; dashboard.value = data; className.value = data.className }
  catch (e) { if (run === sequence) { error.value = learningError(e); if (dashboard.value) className.value = dashboard.value.className } }
  finally { if (run === sequence) loading.value = false }
}
function openRecord(record) { router.push(recordRoute(record)) }
function overdue(record) { return !record.submitted && record.dueAt && new Date(record.dueAt) < new Date() }
async function editReflection(record) { reflectionRecord.value = record; reflectionText.value = record.reflection || ''; reflectionError.value = ''; await nextTick(); reflectionInput.value?.focus() }
function closeReflection() { if (!saving.value) reflectionRecord.value = null }
async function saveReflection() {
  if (saving.value || !reflectionText.value.trim()) return
  saving.value = true; reflectionError.value = ''
  try { await learningApi.reflect(reflectionRecord.value.code, reflectionText.value.trim(), reflectionRecord.value.feedbackRevision); reflectionRecord.value = null; await load() }
  catch (e) { reflectionError.value = learningError(e) }
  finally { saving.value = false }
}
onMounted(load)
onBeforeUnmount(() => { sequence++ })
</script>
<style scoped>
