9;color: #64748b}.learning-tabs button.active span{background:#eef2ff;color: #6366f1}.panel-heading{display:flex;align-items:center;justify-content:space-between;padding:15px 18px;border-bottom:1px solid #eef2f7;gap:10px}.panel-heading h2{margin:0;color: #334155;font-size:14px;font-weight:600}.panel-heading select{max-width:180px;min-width:0;border:1px solid #e4e9f3;border-radius:6px;padding:5px 8px;background:white;color: #64748b;font-size: 12px}.ranking-panel :deep(.learning-ranking){max-height:350px}.learning-empty{padding:65px 20px;color: #64748b;text-align:center;font-size: 13px}.record-table-wrap{overflow:auto}.record-table{width:100%;border-collapse:collapse;font-size: 12px}.record-table th{text-align:left;background:#f8fafc;color: #64748b;font-weight:500;padding:13px 18px;white-space:nowrap}.record-table td{padding:17px 18px;border-top:1px solid #eef2f7;vertical-align:middle}.record-table td strong{font-size: 13px;font-weight:600;color: #334155;min-width:150px;display:block}.record-class{display:block;margin-top:6px;font-size: 11px;color: #64748b}.record-status{display:inline-block;padding:4px 8px;border-radius:5px;white-space:nowrap;background:#f1f5f9;color: #64748b;font-size: 11px}.record-status.done{color: #047857;background:#ecfdf5}.record-status.pending{color: #b45309;background:#fffbeb}.record-table .overdue{color: #dc2626}.text-action{border:0;background:transparent;color: #6366f1;padding:4px 0;white-space:nowrap}.feedback-list article,.point-list article{padding:20px;border-bottom:1px solid #eef2f7}.feedback-list article:last-child,.point-list article:last-child{border:0}.feedback-list article>header,.point-list header{display:flex;justify-content:space-between;align-items:center;gap:14px}.feedback-list strong,.point-list strong{font-size: 13px;font-weight:600}.score-tag{white-space:nowrap;background:#eef2ff;border-radius:5px;padding:4px 8px;font-size: 12px;color: #6366f1}.teacher-comment{line-height:1.9;color: #475569;margin:15px 0;white-space:pre-wrap;overflow-wrap:anywhere}.feedback-list footer{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:18px}.feedback-list footer>span{color: #64748b;font-size: 11px}.feedback-list footer>div{display:flex;gap:8px}.reflection-content{background:#f8fafc;border:1px solid #eef2f7;border-radius:8px;padding:14px}.reflection-content>strong{color: #64748b;font-size: 12px}.reflection-content p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8;margin:8px 0 10px}.point-list header b{color: #6366f1;font-size:17px}.point-items{display:flex;flex-wrap:wrap;gap:10px;margin-top:15px}.point-items>span{border:1px solid #e4e9f3;border-radius:6px;padding:7px 10px;color: #64748b;font-size: 12px}.point-items b{margin-left:12px;color: #6366f1;font-weight:500}.learning-error{padding:12px;background:#fef2f2;color: #dc2626;border-radius:7px;margin:0 0 14px}.learning-mask{position:fixed;inset:0;z-index:140;display:flex;align-items:center;justify-content:center;padding:20px;background:#0f172a66}.learning-dialog{width:100%;max-width:600px;max-height:88vh;overflow:auto;background:white;border-radius:12px;padding:24px;box-shadow:0 12px 40px #0f172a26}.learning-dialog header{display:flex;align-items:center;justify-content:space-between}.learning-dialog h2{font-size:17px;font-weight:600;margin:0}.learning-dialog h3{font-size:14px;font-weight:600;margin:20px 0}.learning-dialog label{display:block;font-size: 13px;font-weight:600;margin:16px 0 10px}.dialog-comment{background:#f8fafc;padding:12px;border-radius:7px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere}.learning-dialog textarea{width:100%;box-sizing:border-box;border:1px solid #dbe2ec;border-radius:7px;resize:vertical;padding:12px;line-height:1.8}.learning-dialog footer{display:flex;justify-content:space-between;align-items:center;margin-top:18px}.learning-dialog footer span{color: #64748b;font-size: 12px}:is(button,select,textarea):focus-visible{outline:2px solid #a5b4fc;outline-offset:2px}@media(max-width:1100px){.learning-columns{grid-template-columns:minmax(0,1fr) 300px}.learning-tabs{gap:16px}.record-table :is(th,td){padding:13px 12px}}@media(max-width:850px){.my-learning{padding:14px}.learning-columns{grid-template-columns:1fr}.learning-sidebar{display:grid;grid-template-columns:1fr 1fr;align-items:start}.learning-stats{gap:10px}.learning-stats>div{padding:14px}.learning-tabs{gap:20px}}@media(max-width:560px){.learning-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.learning-sidebar{grid-template-columns:1fr}.learning-toolbar h1{font-size:15px}.learning-tabs{gap:16px;padding:0 12px}.learning-tabs button{font-size: 12px}.feedback-list footer{align-items:flex-start;flex-direction:column}.learning-dialog{padding:18px}}
</style>
